                 "O" => value.ToUniversalTime().ToString(RoundtripZFormat, CultureInfo.InvariantCulture),
                 "o" => value.ToUniversalTime().ToString(RoundtripZFormat, CultureInfo.InvariantCulture),
                 "R" => value.ToString("r", CultureInfo.InvariantCulture),
                 _ => value.ToString(format, CultureInfo.InvariantCulture)
