                 int size = checked(numWholeOrPartialInputBlocks * 4);
                 char[] output = new char[size];

                 int numBase64Chars = Convert.ToBase64CharArray(value, 0, value.Length, output, 0);

                 int i = 0;
                 for (; i < numBase64Chars; i++)
                 {
                     char ch = output[i];
                     if (ch == '+')
                     {
                         output[i] = '-';
                     }
                     else
                     {
                         if (ch == '/')
                         {
                             output[i] = '_';
                         }
                         else
                         {
                             if (ch == '=')
                             {
                                 break;
                             }
                         }
                     }
                 }

                 return new string(output, 0, i);
